### 3. Create `src/components/shared/MonitoringSettingsCard.tsx` (NEW FILE)
A settings card component for the monitoring section in Settings:

```tsx
import { Bell, Calendar, ArrowRight } from "lucide-react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useMonitoring } from "@/hooks/use-monitoring";
import { useScans } from "@/hooks/use-scans";

export function MonitoringSettingsCard({ isPro }: { isPro: boolean }) {
  const { monitoredUrls } = useMonitoring();
  const { data: scans = [] } = useScans();

  const monitoredScans = scans.filter(s => s.status === "completed" && monitoredUrls.has(s.url));

  // Show only the latest scan per URL
  const uniqueMonitored = Object.values(
    monitoredScans.reduce<Record<string, typeof scans[0]>>((acc, scan) => {
      if (!acc[scan.url] || new Date(scan.created_at) > new Date(acc[scan.url].created_at)) {
        acc[scan.url] = scan;
      }
      return acc;
    }, {})
  );

  if (!isPro) {
    return (
      <Card className="border-border/50 shadow-none">
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Bell className="h-4 w-4 text-muted-foreground" />
              <CardTitle className="text-base">Monthly Monitoring</CardTitle>
            </div>
            <Badge variant="outline" className="border-amber-200 bg-amber-50 text-amber-700 text-xs">
              Pro Feature
            </Badge>
          </div>
          <CardDescription>
            Automatically re-scan your URLs every month and get alerted when conversion scores drop.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="rounded-lg bg-muted/40 p-4 text-sm text-muted-foreground">
            Upgrade to Pro to enable monthly score monitoring for your key pages and receive email alerts when CRO scores drop below your threshold.
          </div>
          <Button className="mt-4 w-full" asChild>
            <Link to="/pricing">Upgrade to Pro</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border/50 shadow-none">
      <CardHeader>
        <div className="flex items-center gap-2">
          <Bell className="h-4 w-4 text-muted-foreground" />
          <CardTitle className="text-base">Monthly Monitoring</CardTitle>
        </div>
        <CardDescription>
          {uniqueMonitored.length} URL{uniqueMonitored.length !== 1 ? "s" : ""} being monitored.
          Automated re-scans run on the 1st of each month.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {uniqueMonitored.length === 0 ? (
          <div className="rounded-lg border border-dashed border-border/60 p-6 text-center">
            <Bell className="mx-auto h-8 w-8 text-muted-foreground/40 mb-2" />
            <p className="text-sm text-muted-foreground">No URLs monitored yet.</p>
            <p className="text-xs text-muted-foreground/70 mt-1">
              Open any report → menu → "Monitor Monthly" to start tracking.
            </p>
            <Button variant="outline" size="sm" className="mt-3 border-border/50" asChild>
              <Link to="/reports">View Reports</Link>
            </Button>
          </div>
        ) : (
          <div className="divide-y divide-border/50">
            {uniqueMonitored.map(scan => {
              let hostname = scan.url;
              try { hostname = new URL(scan.url).hostname.replace("www.", ""); } catch {}
              return (
                <div key={scan.id} className="flex items-center justify-between py-3 first:pt-0 last:pb-0">
                  <div className="flex items-center gap-2 min-w-0">
                    <Bell className="h-3.5 w-3.5 shrink-0 text-primary" />
                    <span className="text-sm truncate">{hostname}</span>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    <div className="flex items-center gap-1 text-xs text-muted-foreground">
                      <Calendar className="h-3 w-3" />
                      <span>Next: {getNextScanDate()}</span>
                    </div>
                    <Button variant="ghost" size="sm" asChild className="h-7 px-2">
                      <Link to={`/reports/${scan.id}`}>
                        <ArrowRight className="h-3.5 w-3.5" />
                      </Link>
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        <Separator />

        <p className="text-xs text-muted-foreground">
          Score drop alerts are sent to <span className="font-medium text-foreground">{/* email from profile */}</span> when a monitored URL drops more than 5 points month-over-month.
        </p>
      </CardContent>
    </Card>
  );
}

// Returns "Feb 1" style date for the 1st of next month
function getNextScanDate() {
  const now = new Date();
  const next = new Date(now.getFullYear(), now.getMonth() + 1, 1);
  return next.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}
```

The MonitoringSettingsCard needs the user's email. Pass it as a prop: `{ isPro: boolean; userEmail?: string }`. Update the email line to show `{userEmail ?? "your email"}`.

### 4. Update `src/pages/Settings.tsx`
Read this file first to understand its tab structure.

Find the Notifications tab section (it uses `NOTIF_STORAGE_KEY = "crobot_notifications"`). Add the `MonitoringSettingsCard` to the **Notifications** tab, at the top of that tab's content, before the existing notification toggles.

Import:
```tsx
import { MonitoringSettingsCard } from "@/components/shared/MonitoringSettingsCard";
```

The component needs:
```tsx
<MonitoringSettingsCard
  isPro={profile?.plan === "pro" || profile?.plan === "agency"}
  userEmail={profile?.email}
/>
```

## Conventions
- No `any` types
- No arbitrary font sizes (use text-xs, text-sm, text-2xs, text-base, etc.)
- No bg-white → use bg-card
- No hardcoded hex colors — use semantic tokens
- All hooks before any early returns
- Import type for type-only imports
- Use existing shadcn/ui components only
- `toast` from sonner
- Check that `Bell`, `BellOff`, `Calendar`, `ArrowRight` are imported where needed

Build all files completely. Read the files before editing them.

